"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78241"],{74735(e){e.exports=JSON.parse('{"id":"V4-089","slug":"black-scholes-model","term":"Black-Scholes Model","also_known_as":[],"difficulty":"Advanced","definition":"The Black-Scholes model is a mathematical formula for estimating the fair price of a European-style option, based on the price of the underlying asset, the exercise price, time to expiry, interest rates and volatility.","explanation":["The model was published in 1973 by economists Fischer Black and Myron Scholes, with important contributions from Robert Merton. Scholes and Merton received the Nobel Prize in Economics in 1997; Black had died in 1995.","The model\u2019s key insight is that an option\u2019s risk can be hedged by holding the right amount of the underlying asset, so its price can be calculated without knowing investors\u2019 attitudes to risk. The formula requires five main inputs: the current price of the underlying, the exercise price, the time until expiry, the risk-free interest rate and the expected volatility of the underlying.","For example, traders can use the model to estimate the value of a call option on a share, or work backwards from an option\u2019s market price to find its implied volatility.","The model rests on simplifying assumptions, such as constant volatility, continuous trading, no transaction costs and returns that follow a lognormal distribution. Real markets do not meet these assumptions, which helps explain volatility skew. Despite its limits, Black-Scholes transformed options markets and remains a foundation of financial theory."],"note":"","total":1725,"prev":{"slug":"bitcoin","term":"Bitcoin"},"next":{"slug":"black-swan-event","term":"Black Swan Event"}}')}}]);